class Solution {
public:
    int minDeletionSize(vector<string>& strs) {
        int answer = 0;
        for (int col = 0; col < (int)strs[0].size(); ++col)
            for (int row = 1; row < (int)strs.size(); ++row)
                if (strs[row][col] < strs[row - 1][col]) {
                    ++answer;
                    break;
                }
        return answer;
    }
};
